using CoreBanking.Ledger.Domain.Customers;

namespace CoreBanking.Ledger.Domain.Tests.Customers;

public class CpfNumberTests
{
    // Fictitious CPF generated by the check digit algorithm. It belongs to no one.
    private const string ValidCpf = "39053344705";

    [Fact]
    public void Parse_ValidWithMask_Normalizes()
    {
        var cpf = CpfNumber.Parse("390.533.447-05");

        Assert.Equal(ValidCpf, cpf.Value);
    }

    [Fact]
    public void Parse_ValidWithoutMask_KeepsDigits()
    {
        var cpf = CpfNumber.Parse(ValidCpf);

        Assert.Equal(ValidCpf, cpf.Value);
    }

    [Theory]
    [InlineData("39053344715")] // first check digit wrong
    [InlineData("39053344706")] // second check digit wrong
    public void Parse_InvalidCheckDigit_Throws(string input)
    {
        var ex = Assert.Throws<DomainException>(() => CpfNumber.Parse(input));

        Assert.Equal("customer.invalid_document", ex.Code);
    }

    [Theory]
    [InlineData("00000000000")]
    [InlineData("11111111111")]
    public void Parse_RepeatedDigits_Throws(string input)
    {
        var ex = Assert.Throws<DomainException>(() => CpfNumber.Parse(input));

        Assert.Equal("customer.invalid_document", ex.Code);
    }

    [Theory]
    [InlineData("")]
    [InlineData("3905334470")]
    [InlineData("390533447051")]
    public void Parse_WrongLength_Throws(string input)
    {
        var ex = Assert.Throws<DomainException>(() => CpfNumber.Parse(input));

        Assert.Equal("customer.invalid_document", ex.Code);
    }

    [Theory]
    [InlineData("390.533.447-0A")]
    [InlineData("390 533 447 05")]
    public void Parse_UnexpectedCharacters_Throws(string input)
    {
        var ex = Assert.Throws<DomainException>(() => CpfNumber.Parse(input));

        Assert.Equal("customer.invalid_document", ex.Code);
    }
}
